
import { z } from "zod";

/**
 * Create Event Validation
 *
 * PURPOSE:
 * Validate event information before saving
 * a new event to MongoDB.
 *
 * FEATURES:
 * - Event title validation
 * - Description validation
 * - Category validation
 * - Image URL validation
 * - Location validation
 * - Future event date validation
 *
 * IMAGE RULES:
 * - Any valid HTTPS image URL is allowed.
 * - Local HTTP uploads are allowed in development.
 * - Other HTTP URLs are rejected.
 *
 * SECURITY:
 * - Unknown fields are rejected.
 * - Organizer identity comes from JWT.
 * - createdAt is generated by the server.
 */

// --------------------------------------------
// IMAGE URL VALIDATION
// --------------------------------------------

const imageUrlValidation = z.url().refine(
  (value) => {
    const url = new URL(value);

    // Allow HTTPS image URLs.
    if (url.protocol === "https:") {
      return true;
    }

    // Allow local server uploads in development.
    if (process.env.NODE_ENV !== "production") {
      const allowedOrigins = [
        "http://localhost:5001",
        "http://127.0.0.1:5001",
      ];

      const isLocalUpload =
        allowedOrigins.includes(url.origin) &&
        /^\/uploads\/[a-f0-9-]+\.webp$/i.test(
          url.pathname
        ) &&
        url.search === "" &&
        url.hash === "";

      return isLocalUpload;
    }

    return false;
  },
  {
    message:
      "Please provide an HTTPS image URL or a valid local upload URL.",
  }
);

// --------------------------------------------
// CREATE EVENT VALIDATION
// --------------------------------------------

export const createEventValidation = z.strictObject({
  /**
   * Event title:
   * Minimum 5, maximum 120 characters.
   */
  title: z
    .string()
    .trim()
    .min(5, "Event title must contain at least 5 characters.")
    .max(120, "Event title cannot exceed 120 characters."),

  /**
   * Event description:
   * Minimum 20, maximum 5000 characters.
   */
  description: z
    .string()
    .trim()
    .min(20, "Description must contain at least 20 characters.")
    .max(5000, "Description cannot exceed 5000 characters."),

  /**
   * Event category.
   */
  eventType: z
    .string()
    .trim()
    .min(2, "Please enter a valid event category.")
    .max(60, "Category cannot exceed 60 characters."),

  /**
   * Public image URL or local upload URL.
   */
  thumbnailUrl: imageUrlValidation,

  /**
   * Event location.
   */
  location: z
    .string()
    .trim()
    .min(3, "Location must contain at least 3 characters.")
    .max(200, "Location cannot exceed 200 characters."),

  /**
   * Date must be a valid ISO datetime
   * and must be in the future.
   */
  eventDate: z
    .iso
    .datetime({ offset: true })
    .refine(
      (value) =>
        new Date(value).getTime() > Date.now(),
      {
        message: "Event date must be in the future.",
      }
    ),
});

// --------------------------------------------
// TYPESCRIPT TYPE
// --------------------------------------------

/**
 * Infer the validated input type from Zod.
 */
export type CreateEventInput = z.infer<
  typeof createEventValidation
>;
